      fprintf(stderr, "Back-reference: offset=%d, length=%d\n", offset, length);

      z = Q - offset - 1;
      tmp = length + 1;

      fprintf(stderr, "  Copying %d bytes from offset %d\n", tmp, offset+1);

      W {
        *Q++ = *z++;
      }
    } else {
      int sign_bit = get_bit(8);
      int magnitude = get_integer(LITSIZE, 9);
      int literal = (1-2*sign_bit) * magnitude;

      fprintf(stderr, "Literal: sign=%d, mag=%d, value=%d (char '%c')\n", 
              sign_bit, magnitude, literal, (literal>=32 && literal<127) ? literal : '?');

      *Q++ = literal;
    }

    fprintf(stderr, "  Buffer size now: %ld bytes\n", Q - buf);
  }

  fprintf(stderr, "\n=== Decoding complete: %ld bytes ===\n", Q - buf);
  printf("%s", buf);
}
EOF

echo "=== Compiling instrumented decoder ==="
gcc -O0 -g decomp_trace.c -o decomp_trace 2>&1
echo "Status: $?"
echo ""

echo "=== Testing with single character input (14 bytes) ==="
echo "Input bytes: [1,13,248,132,73,1,1,1,1,1,1,1,1]"
echo ""
cat test_single.comp | ./decomp_trace 2>&1 | head -100
