# Create an instrumented version of the decoder to trace its execution
# This will help us understand where the byte stream desynchronization occurs

cat > decomp_trace.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#define W for (i=0;i<tmp;i++)

int i;
int radix = 255;
int fraction;
long range = 1;
int tmp;
int cc[1000000];

int OFF1 = 5;
int OFF2 = 2;
int INTOFF = 9;
int LITSIZE = 4;

int ll = 0;
int byte_count = 0;

int gc() {
  unsigned char c = (unsigned char)getchar();
  byte_count++;
  fprintf(stderr, "  [gc#%d: read byte %d (0x%02x)]\n", byte_count, (int)c, (int)c);
  return (int)c;
}

int get_bit(int ctx) {
  fprintf(stderr, "[get_bit ctx=%d: range=%ld, fraction=%d]\n", ctx, range, fraction);

  if ( range < radix ) {
    fprintf(stderr, "  normalize: range<radix, multiplying by %d\n", radix);
    range *= radix;
    fraction *= radix;
    int byte_val = gc();
    fraction += byte_val - 1;
    fprintf(stderr, "  after normalize: range=%ld, fraction=%d\n", range, fraction);
  }

  int *counts = cc + ctx * 2;
  int split = range * -~*counts / (*counts + counts[ 1 ] + 2);
  int the_bit = fraction >= split;

  fprintf(stderr, "  split=%d, fraction=%d, bit=%d\n", split, fraction, the_bit);

  fraction -= split*the_bit;
  range = the_bit ? range-split : split;

  fprintf(stderr, "  after bit: range=%ld, fraction=%d\n", range, fraction);

  counts[ the_bit ]++;
  return the_bit;
}

int get_integer(int tmp, int ctx) {
  fprintf(stderr, "\n[get_integer tmp=%d, ctx=%d]\n", tmp, ctx);

  int subtract_it = 1<<tmp;
  int result_ans = 1;
  ctx*=99;

  fprintf(stderr, "  subtract_it=%d, reading unary bit_len...\n", subtract_it);

  int unary_count = 0;
  while (!get_bit(++tmp+ctx)) {
    unary_count++;
  }
  fprintf(stderr, "  unary zeros=%d, bit_len=%d\n", unary_count, unary_count);

  tmp--;
  fprintf(stderr, "  reading %d magnitude bits...\n", tmp);

  W {
    result_ans = result_ans*2 | get_bit(ctx);
  }

  int final = result_ans - subtract_it;
  fprintf(stderr, "  result_ans=%d, final=%d\n\n", result_ans, final);

  return final;
}

int main() {
  fprintf(stderr, "=== Decoder trace started ===\n");
  fprintf(stderr, "Initial: range=%ld, fraction=%d\n\n", range, fraction);

  int tmp,i,j = get_integer(9, 0);
  fprintf(stderr, "\n*** Operation count: %d ***\n\n", j);

  char* z;

  char buf[10000];
  char* Q = buf;

  int op_num = 0;
  while (j--) {
    op_num++;
    fprintf(stderr, "\n=== Operation #%d ===\n", op_num);

    int op_type = get_bit(1);
    fprintf(stderr, "op_type bit: %d\n", op_type);

    if (op_type) {
      int offset = get_integer(OFF1, 2);
      int length = get_integer(OFF2, 3);
      fprintf(stderr, "Back-reference: offset=%d, length=%d\n", offset, length);

      z = Q - offset - 1;
      tmp = length + 1;

      fprintf(stderr, "  Copying %d bytes from offset %d\n", tmp, offset+1);

      W {
        *Q++ = *z++;
      }
    } else {
      int sign_bit = get_bit(8);
      int magnitude = get_integer(LITSIZE, 9);
      int literal = (1-2*sign_bit) * magnitude;

      fprintf(stderr, "Literal: sign=%d, mag=%d, value=%d (char '%c')\n", 
              sign_bit, magnitude, literal, (literal>=32 && literal<127) ? literal : '?');

      *Q++ = literal;
    }

    fprintf(stderr, "  Buffer size now: %ld bytes\n", Q - buf);
  }

  fprintf(stderr, "\n=== Decoding complete: %ld bytes ===\n", Q - buf);
  printf("%s", buf);
}
EOF

echo "=== Compiling instrumented decoder ==="
gcc -O0 -g decomp_trace.c -o decomp_trace 2>&1
echo "Status: $?"
echo ""

echo "=== Testing with single character input (14 bytes) ==="
echo "Input bytes: [1,13,248,132,73,1,1,1,1,1,1,1,1]"
echo ""
cat test_single.comp | ./decomp_trace 2>&1 | head -100

