int OFF1 = 5;
int OFF2 = 2;
int INTOFF = 9;
int LITSIZE = 4;

int ll = 0;

int gc() {
  unsigned char c = (unsigned char)getchar();
  fprintf(stderr, "[gc] byte=%d\n", (int)c);
  return (int)c;
}

int get_bit(int ctx) {
  long range_before = range;
  int fraction_before = fraction;

  if ( range < radix ) {
    fprintf(stderr, "[NORMALIZE ctx=%d] range=%ld -> ", ctx, range_before);
    range *= radix;
    fraction *= radix;
    int byte_read = gc();
    fraction += byte_read - 1;
    fprintf(stderr, "range=%ld, fraction=%d (byte=%d)\n", range, fraction, byte_read);
  }

  int *counts = cc + ctx * 2;
  int split = range * -~*counts / (*counts + counts[ 1 ] + 2);
  int the_bit = fraction >= split;

  fprintf(stderr, "[get_bit ctx=%d] range=%ld frac=%d counts=[%d,%d] split=%d bit=%d\n", 
          ctx, range, fraction, counts[0], counts[1], split, the_bit);

  fraction -= split*the_bit;
  range = the_bit ? range-split : split;
  counts[ the_bit ]++;

  return the_bit;
}

int get_integer(int tmp, int ctx) {
  fprintf(stderr, "\n[get_integer START] tmp=%d ctx=%d\n", tmp, ctx);

  int subtract_it = 1<<tmp;
  int result_ans = 1;
  ctx*=99;

  fprintf(stderr, "[get_integer] subtract_it=%d, ctx_scaled=%d\n", subtract_it, ctx);
  fprintf(stderr, "[get_integer] === UNARY PHASE ===\n");

  int bit_count = 0;
  while (!get_bit(++tmp+ctx)) {
    bit_count++;
    fprintf(stderr, "  -> Unary zero #%d (context=%d)\n", bit_count, tmp+ctx);
  }

  fprintf(stderr, "  -> Unary terminated: %d zeros, terminating bit at context=%d\n", bit_count, tmp+ctx);
  tmp--;

  fprintf(stderr, "[get_integer] === MAGNITUDE PHASE: %d bits, context=%d ===\n", tmp, ctx);

  W {
    int bit = get_bit(ctx);
    result_ans = result_ans*2 | bit;
    fprintf(stderr, "  -> Magnitude bit %d/%d = %d, running_value=%d\n", i+1, tmp, bit, result_ans);
  }

  int final_result = result_ans - subtract_it;
  fprintf(stderr, "[get_integer END] result=%d (%d - %d)\n\n", final_result, result_ans, subtract_it);

  return final_result;
}

int main() {
