  int tmp,i,j = get_integer(9, 0);
  fprintf(stderr, "\n=== MAIN: Operation count decoded = %d ===\n\n", j);

  char* z;
  char buf[10000];
  char* Q = buf;

  while (j--) {
    fprintf(stderr, "[Operation #%d remaining]\n", j+1);
    if (get_bit(1)) {
      int offset = get_integer(OFF1, 2) + 1;
      int length = get_integer(OFF2, 3) + 1;
      fprintf(stderr, "BACKREF: offset=%d length=%d\n", offset, length);
      z = Q - offset;
      tmp = length;
      W {
        *Q++ = *z++;
      }
    } else {
      int sign_bit = get_bit(8);
      int magnitude = get_integer(LITSIZE, 9);
      int literal = (1-2*sign_bit) * magnitude;
      fprintf(stderr, "LITERAL: %d ('%c')\n\n", literal, literal >= 32 && literal < 127 ? literal : '?');
      *Q++ = literal;
    }
  }

  printf("%s", buf);
}

